<?php

declare(strict_types=1);

// Export of a database generated by this exact disposable fixture only. Never an operator export tool.
$name = getenv('E2E_DATABASE');
if (!preg_match('/^imagine_e2e_(classic|hpos)_test$/D', $name ?: '')) {
    throw new RuntimeException('SYNTHETIC_DATABASE_REQUIRED');
}
$db = new PDO('mysql:unix_socket=/scratch/mariadb.sock;dbname=' . $name . ';charset=utf8mb4', 'root', '');
foreach ($db->query('SHOW TABLES')->fetchAll(PDO::FETCH_COLUMN) as $table) {
    if (!preg_match('/^[a-zA-Z0-9_]+$/D', $table)) {
        throw new RuntimeException('SCHEMA_REFUSED');
    }
    echo $db->query('SHOW CREATE TABLE `' . $table . '`')->fetch(PDO::FETCH_NUM)[1] . ";\n";
    foreach ($db->query('SELECT * FROM `' . $table . '`')->fetchAll(PDO::FETCH_ASSOC) as $row) {
        $values = array_map(static fn ($v) => $v === null ? 'NULL' : $db->quote((string) $v), array_values($row));
        echo 'INSERT INTO `' . $table . '` (`' . implode('`,`', array_keys($row)) . '`) VALUES ('
            . implode(',', $values) . ");\n";
    }
}
